@writer('kahani')
def w_kahani(prompts, grade, marks=5, words='120'):
    """कैसे बनती है कविता/कहानी: prompts are (form, prompt) where form is कहानी/कविता."""
    c = cyc('kahani')
    shape = {'कहानी': 'आकर्षक आरंभ, सीमित पात्र, स्पष्ट देशकाल, द्वंद्व और चरम बिंदु, स्वाभाविक संवाद, उद्देश्यपूर्ण अंत, उपयुक्त शीर्षक',
             'कविता': 'केंद्रीय भाव, बिंब और प्रतीक, लय (छंदबद्ध या मुक्त), सटीक शब्द-चयन, अलंकार का सहज प्रयोग, प्रभावी अंतिम पंक्तियाँ'}

    def g(r):
        form, p = c.pick(r, prompts)
        task = f'लगभग {words} शब्दों में एक लघु कहानी लिखिए।' if form == 'कहानी' else 'लगभग 8-12 पंक्तियों की एक छोटी कविता लिखिए।'
        return {'stem': f'{p} {task}',
                'answer': f'{form} के तत्त्व: {shape[form]}।',
                'key': f'अंक-विभाजन ({marks}): विधा के तत्त्वों का निर्वाह 1, विषय-वस्तु और मौलिकता {marks - 2}, भाषा 1।', 'marks': marks, 'minutes': 8, 'gap': 'G5'}
    return g


